{
  "status": "SUPPORTED",
  "task_summary": "Prepare living room for two people with refreshment settings and accessible entertainment control.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "Hold beverage and food for one person",
        "required_count": 2
      ,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cup", "plate", "snack"],
        "required_properties": ["holds liquid", "holds solid food"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Control the television",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["remote", "controller"],
        "required_properties": ["operates television"]
      },
      {
        "id": "surface",
        "entity_kind": "REGION",
        "function": "Support objects",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "shelf"],
        "required_properties": ["flat", "stable"]
      },
      {
        "id": "seating_area",
        "entity_kind": "REGION",
        "function": "Provide place to sit",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["chair", "sofa"],
        "required_properties": ["for sitting"]
      },
      {
        "id": "television",
        "entity_kind": "FIXED_TARGET",
        "function": "Display video content",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["tv", "screen"],
        "required_properties": ["displays video"]
      }
    ],
    "functional_relations": [
      {
        "id": "refreshment_near_seating",
        "relation": "is located near",
        "participant_roles": ["refreshment_setting", "seating_area"],
        "required": true
      },
      {
        "id": "control_accessible",
        "relation": "is accessible to",
        "participant_roles": ["entertainment_control", "seating_area"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "setup_refreshments",
        "operation": "place",
        "participant_roles": ["refreshment_setting", "surface"],
        "operation_count": 2
      },
      {
        "id": "position_remote",
        "operation": "move",
        "participant_roles": ["entertainment_control", "surface"],
        "operation_count": 1
      }
    ]
  }
,
